class UnionFind {
  int[] parent, rank;
  UnionFind(int n) { parent = new int[n]; rank = new int[n]; for (int i = 0; i < n; i++) parent[i] = i; }
  int find(int x) { return parent[x] == x ? x : (parent[x] = find(parent[x])); }
  boolean union(int a, int b) {
    int ra = find(a), rb = find(b);
    if (ra == rb) return false;
    if (rank[ra] < rank[rb]) { int t = ra; ra = rb; rb = t; }
    parent[rb] = ra; if (rank[ra] == rank[rb]) rank[ra]++;
    return true;
  }
}

static String lookup(Node root, int ip) {
  String best = null; Node cur = root;
  for (int i = 31; i >= 0 && cur != null; i--) {
    if (cur.hop != null) best = cur.hop;
    cur = cur.ch[(ip >>> i) & 1];
  }
  if (cur != null && cur.hop != null) best = cur.hop;
  return best;
}

