class Trie {
  static class Node { Node[] next = new Node[26]; boolean end; }
  Node root = new Node();
  void insert(String w) {
    Node cur = root;
    for (char c : w.toCharArray()) {
      int i = c - 'a';
      if (cur.next[i] == null) cur.next[i] = new Node();
      cur = cur.next[i];
    }
    cur.end = true;
  }
  boolean search(String w) {
    Node cur = root;
    for (char c : w.toCharArray()) {
      cur = cur.next[c - 'a'];
      if (cur == null) return false;
    }
    return cur.end;
  }
}
